// Fonts for pdoom-akari, subset to the characters the film prints and embedded so index.html works straight from disk.
// Zen Kaku Gothic New (Bold, Black), Dela Gothic One, Zen Old Mincho (Bold), DotGothic16: SIL Open Font License 1.1
// (fonts/OFL.txt), from github.com/google/fonts. The full .ttf files are in fonts/. To add characters, re-run the
// subset (fontTools: pyftsubset <font>.ttf --text-file=… --flavor=woff) and re-embed. The family names match ILL.F.
MV.onInit(async () => {
  const faces = [
    ['Zen Kaku Gothic New', 'data:font/woff;base64,', { weight: '700' }],
    ['Zen Kaku Gothic New', 'data:font/woff;base64,', { weight: '900' }],
    ['Dela Gothic One', 'data:font/woff;base64,', { weight: '100 900' }],
    ['Zen Old Mincho', 'data:font/woff;base64,', { weight: '100 900' }],
    ['DotGothic16', 'data:font/woff;base64,', { weight: '100 900' }],
  ];
  for (const [family, url, desc] of faces) { const ff = new FontFace(family, `url(${url})`, desc); await ff.load(); document.fonts.add(ff); }
});
